representation.shell_command:
python3 - "$(inputs.pdb.path)" > out.fasta <<'PYEOF'
import sys
m = {'ALA':'A','ARG':'R','ASN':'N','ASP':'D','CYS':'C','GLN':'Q','GLU':'E','GLY':'G','HIS':'H','ILE':'I','LEU':'L','LYS':'K','MET':'M','PHE':'F','PRO':'P','SER':'S','THR':'T','TRP':'W','TYR':'Y','VAL':'V','MSE':'M'}
path = sys.argv[1]
seqres = {}
order = []
atomseq = {}
seen = set()
pdbid = ''
for line in open(path):
    rec = line[:6]
    if rec == 'HEADER':
        pdbid = line[62:66].strip()
    elif rec == 'SEQRES':
        ch = line[11]
        if ch not in seqres:
            seqres[ch] = []
            order.append(ch)
        for t in line[19:70].split():
            seqres[ch].append(m.get(t, 'X'))
    elif rec in ('ATOM  ', 'HETATM'):
        if line[12:16].strip() != 'CA':
            continue
        res = line[17:20].strip()
        if res not in m:
            continue
        ch = line[21]
        key = (ch, line[22:27])
        if key in seen:
            continue
        seen.add(key)
        atomseq.setdefault(ch, []).append(m[res])
if seqres:
    src, data, chains = 'SEQRES', seqres, order
else:
    src, data, chains = 'ATOM_CA', atomseq, sorted(atomseq)
for ch in chains:
    s = ''.join(data[ch])
    sys.stdout.write('>%s_%s %s len=%d\n' % (pdbid or 'PDB', ch, src, len(s)))
    for i in range(0, len(s), 60):
        sys.stdout.write(s[i:i+60] + '\n')
PYEOF
